class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        map<int, int> first;
        first[0] = -1;
        int bal = 0, best = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            bal += nums[i] ? 1 : -1;
            if (first.count(bal)) best = max(best, i - first[bal]);
            else first[bal] = i;
        }
        return best;
    }
};
